"use client";

import { useEffect, useRef, useState } from "react";
import { DayPicker, type DateRange } from "react-day-picker";
import "react-day-picker/dist/style.css";
import styles from "./styles.module.css";

interface BoardSearchProps {
  onSearch: (params: { keyword: string; range?: DateRange }) => void;
  onWriteClick?: () => void;
}

function formatDate(date?: Date) {
  if (!date) return "YYYY.MM.DD";
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const d = String(date.getDate()).padStart(2, "0");
  return `${y}.${m}.${d}`;
}

export default function BoardSearch({
  onSearch,
  onWriteClick,
}: BoardSearchProps) {
  const [keyword, setKeyword] = useState("");

  // range: 실제로 확정되어 버튼 라벨에 표시되는 값
  const [range, setRange] = useState<DateRange | undefined>();
  // draftRange: 팝업 안에서 선택 중인 임시값 (확인 누르기 전까지는 여기에만 반영)
  const [draftRange, setDraftRange] = useState<DateRange | undefined>();

  const [isCalendarOpen, setIsCalendarOpen] = useState(false);
  const calendarWrapRef = useRef<HTMLDivElement>(null);

  const openCalendar = () => {
    setDraftRange(range); // 팝업 열 때 현재 확정값으로 초기화
    setIsCalendarOpen(true);
  };

  const closeCalendar = () => {
    setIsCalendarOpen(false);
  };

  const handleConfirm = () => {
    setRange(draftRange); // 확인 눌러야 실제 값에 반영
    closeCalendar();
  };

  const handleCancel = () => {
    setDraftRange(range); // 임시 선택 버리고 원래 값으로 되돌림
    closeCalendar();
  };

  // 팝업 바깥 클릭하면 선택 취소하고 닫기 (확인을 눌러야만 값이 반영되도록)
  useEffect(() => {
    if (!isCalendarOpen) return;
    const handleClickOutside = (event: MouseEvent) => {
      if (
        calendarWrapRef.current &&
        !calendarWrapRef.current.contains(event.target as Node)
      ) {
        handleCancel();
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isCalendarOpen, range]);

  const dateLabel = range?.from
    ? `${formatDate(range.from)} - ${formatDate(range.to)}`
    : "YYYY.MM.DD - YYYY.MM.DD";

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault();
    onSearch({ keyword, range });
  };

  return (
    <form className={styles.actionRow} onSubmit={handleSubmit}>
      <div className={styles.leftGroup}>
        <div className={styles.datepickerWrap} ref={calendarWrapRef}>
          <button
            type="button"
            className={styles.datepicker}
            onClick={() => (isCalendarOpen ? closeCalendar() : openCalendar())}
          >
            <svg
              width="24"
              height="24"
              viewBox="0 0 24 24"
              fill="none"
              aria-hidden
            >
              <rect
                x="3"
                y="5"
                width="18"
                height="16"
                rx="2"
                stroke="#777777"
                strokeWidth="1.6"
              />
              <path d="M3 9.5H21" stroke="#777777" strokeWidth="1.6" />
              <path
                d="M8 3V6.5"
                stroke="#777777"
                strokeWidth="1.6"
                strokeLinecap="round"
              />
              <path
                d="M16 3V6.5"
                stroke="#777777"
                strokeWidth="1.6"
                strokeLinecap="round"
              />
            </svg>
            <span className={styles.datepickerText}>{dateLabel}</span>
          </button>

          {isCalendarOpen && (
            <div className={styles.calendarPopover}>
              <DayPicker
                mode="range"
                selected={draftRange}
                onSelect={setDraftRange}
                numberOfMonths={2}
              />

              <div className={styles.calendarActions}>
                <button
                  type="button"
                  className={styles.calendarCancelButton}
                  onClick={handleCancel}
                >
                  취소
                </button>
                <button
                  type="button"
                  className={styles.calendarConfirmButton}
                  onClick={handleConfirm}
                >
                  확인
                </button>
              </div>
            </div>
          )}
        </div>

        <label className={styles.searchField}>
          <svg
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            aria-hidden
          >
            <circle cx="11" cy="11" r="7" stroke="#919191" strokeWidth="1.6" />
            <path
              d="M21 21L16.5 16.5"
              stroke="#919191"
              strokeWidth="1.6"
              strokeLinecap="round"
            />
          </svg>
          <input
            type="text"
            placeholder="제목을 검색해 주세요."
            value={keyword}
            onChange={(event) => setKeyword(event.target.value)}
          />
        </label>

        <button type="submit" className={styles.searchButton}>
          검색
        </button>
      </div>

      <button
        type="button"
        className={styles.writeButton}
        onClick={onWriteClick}
      >
        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden>
          <path
            d="M4 20h4l10-10-4-4L4 16v4z"
            stroke="#ffffff"
            strokeWidth="1.6"
            strokeLinejoin="round"
          />
        </svg>
        트립토크 등록
      </button>
    </form>
  );
}
